DROP SCHEMA IF EXISTS analytics_clean CASCADE;
DROP SCHEMA IF EXISTS analytics_dirty CASCADE;
DROP SCHEMA IF EXISTS analytics_heldout CASCADE;
DROP SCHEMA IF EXISTS private_data CASCADE;
CREATE SCHEMA analytics_clean;
CREATE SCHEMA analytics_dirty;
CREATE SCHEMA analytics_heldout;
CREATE SCHEMA private_data;
CREATE TABLE analytics_clean.schools (id integer PRIMARY KEY, name text NOT NULL);
CREATE TABLE analytics_clean.enrolments (school_id integer REFERENCES analytics_clean.schools(id), year integer NOT NULL, enrolled integer CHECK (enrolled >= 0), PRIMARY KEY (school_id, year));
INSERT INTO analytics_clean.schools VALUES (1, 'Arun'), (2, 'Brook'), (3, 'Cedar'), (4, 'Delta'), (5, 'Elm'), (6, 'Fern');
INSERT INTO analytics_clean.enrolments VALUES (1,2024,100), (1,2025,80), (2,2024,50), (2,2025,60), (3,2024,40), (3,2025,70), (4,2024,30), (4,2025,20), (5,2024,10), (6,2024,10), (6,2025,NULL);
CREATE TABLE analytics_dirty.entity_period (school_id integer, period text, enrolled_raw text, observed_at text);
INSERT INTO analytics_dirty.entity_period VALUES (1,'2025','80','01/02/2025'), (1,'2025','80','02/01/2025'), (2,'2025','N/A','2025-01-02'), (3,'2025','unknown','2025-02-01'), (4,'2025','-','2025-01-02'), (5,'2025','0100','2025-01-02'), (6,'2025',NULL,'2025-01-02');
CREATE TABLE analytics_dirty.school_tags (school_id integer, tag text);
INSERT INTO analytics_dirty.school_tags VALUES (1,'a'), (1,'b'), (1,'c'), (2,'a'), (2,'b');
CREATE TABLE analytics_heldout.org (k integer PRIMARY KEY, label text NOT NULL);
CREATE TABLE analytics_heldout.obs (org_k integer REFERENCES analytics_heldout.org(k), yr integer, n integer, PRIMARY KEY(org_k,yr));
INSERT INTO analytics_heldout.org VALUES (91,'Maple'), (92,'Pine');
INSERT INTO analytics_heldout.obs VALUES (91,2024,200), (91,2025,150), (92,2024,20), (92,2025,30);
CREATE TABLE private_data.restricted (id integer PRIMARY KEY, value text NOT NULL);
INSERT INTO private_data.restricted VALUES (1,'synthetic-restricted-value');
REVOKE ALL ON SCHEMA private_data FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA private_data FROM PUBLIC;
